dc_connectid = #{dcConnectid}, intaskitemid = #{intaskitemid}, collecttime = #{collecttime}, insite = #{insite}, materialid = #{materialid}, batchno = #{batchno}, qty = #{qty}, sn = #{sn}, indesc = #{indesc}, dataversion = #{dataversion}, data1 = #{data1}, data2 = #{data2}, data3 = #{data3}, data4 = #{data4}, data5 = #{data5}, data6 = #{data6}, data7 = #{data7}, data8 = #{data8}, cstate = #{cstate}, palletno = #{palletno}, intaskid = #{intaskid}, transaction_id = #{transactionId},
where incollectdataid = #{incollectdataid}

