with indata as( select aa.statmonth, sum(aa.qty) as qty, count(*) as kindqty from( select sum(col.qty) as qty, pm.matcode, TO_CHAR(col.collecttime,'YYYYMM') AS statmonth
from incollectdata col, pm_material pm where pm.pm_materialid=col.materialid group by pm.matcode, TO_CHAR(col.collecttime,'YYYYMM')
)aa group by aa.statmonth order by aa.statmonth asc ), gw_month as( SELECT month_list.year_id, month_list.month_id, month_list.start_year, month_list.ly_month_id, month_list.ly_start_year, month_list.prev_month_id FROM ( SELECT ny.*, ny.year_id||'01' as start_year, substr(ny.ly_month_id,0,4)||'01' as ly_start_year FROM dim_month ny WHERE month_id >= '202101' AND month_id <= #{month_id} ) month_list WHERE 1=1 ), indata_all as( select gw_month1.year_id, gw_month1.month_id, indata1.qty, indata1.kindqty, null as ly_qty, null as ly_kindqty from gw_month gw_month1 left join indata indata1 on indata1.statmonth=gw_month1.month_id
union all
select gw_month2.year_id, gw_month2.month_id, null as qty, null as kindqty, indata2.qty as ly_qty, indata2.kindqty as ly_kindqty from gw_month gw_month2 left join indata indata2 on indata2.statmonth=gw_month2.ly_month_id ), indata_month as( select year_id, month_id, sum(nvl(qty,0)) as qty, sum(nvl(kindqty,0)) as kindqty, sum(nvl(ly_qty,0)) as ly_qty, sum(nvl(ly_kindqty,0)) as ly_kindqty from indata_all where month_id>(select ly_month_id from dim_month where month_id=#{month_id}) and month_id <= #{month_id} group by year_id, month_id ) select year_id, month_id, round(qty/10000,2) as qty, round(kindqty,2) as kindqty, round(ly_qty/10000,2) as ly_qty, round(ly_kindqty) as ly_kindqty, case when ly_qty=0 then null else (round(((qty-ly_qty)/ly_qty)*100,2)) end as qty_voy, case when ly_kindqty=0 then null else (round(((kindqty-ly_kindqty)/ly_kindqty)*100,2)) end as kindqty_voy from indata_month order by month_id asc

with indata as( select aa.statmonth, sum(aa.qty) as qty, count(*) as kindqty from( select sum(col.qty) as qty, pm.matcode, TO_CHAR(col.collecttime,'YYYYMM') AS statmonth
from outcollectdata col, pm_material pm where pm.pm_materialid=col.materialid group by pm.matcode, TO_CHAR(col.collecttime,'YYYYMM')
)aa group by aa.statmonth order by aa.statmonth asc ), gw_month as( SELECT month_list.year_id, month_list.month_id, month_list.start_year, month_list.ly_month_id, month_list.ly_start_year, month_list.prev_month_id FROM ( SELECT ny.*, ny.year_id||'01' as start_year, substr(ny.ly_month_id,0,4)||'01' as ly_start_year FROM dim_month ny WHERE month_id >= '202101' AND month_id <= #{month_id} ) month_list WHERE 1=1 ), indata_all as( select gw_month1.year_id, gw_month1.month_id, indata1.qty, indata1.kindqty, null as ly_qty, null as ly_kindqty from gw_month gw_month1 left join indata indata1 on indata1.statmonth=gw_month1.month_id
union all
select gw_month2.year_id, gw_month2.month_id, null as qty, null as kindqty, indata2.qty as ly_qty, indata2.kindqty as ly_kindqty from gw_month gw_month2 left join indata indata2 on indata2.statmonth=gw_month2.ly_month_id ), indata_month as( select year_id, month_id, sum(nvl(qty,0)) as qty, sum(nvl(kindqty,0)) as kindqty, sum(nvl(ly_qty,0)) as ly_qty, sum(nvl(ly_kindqty,0)) as ly_kindqty from indata_all where month_id>(select ly_month_id from dim_month where month_id=#{month_id}) and month_id <= #{month_id} group by year_id, month_id ) select year_id, month_id, round(qty/10000,2) as qty, round(kindqty,2) as kindqty, round(ly_qty/10000,2) as ly_qty, round(ly_kindqty) as ly_kindqty, case when ly_qty=0 then null else (round(((qty-ly_qty)/ly_qty)*100,2)) end as qty_voy, case when ly_kindqty=0 then null else (round(((kindqty-ly_kindqty)/ly_kindqty)*100,2)) end kindqty_voy from indata_month order by month_id asc

With Bill_Info As ( Select Bill.Orderno,Bill.Createdate,nvl(Bill.Auditdate,Sysdate) as Auditdate,(SN) as sn From Arrivals_Bill Bill left join t_sys_workday_mm_all mm on ((to_char(Bill.CREATEDATE,'yyyy-MM-dd HH24:mi'))||':00')=mm.WORKDAY_MM Where bill.ARRIVALTYPE='10' and Bill.Createdate>=Trunc(Sysdate-1) Order By Bill.Createdate Asc ), Bill_Info2 As ( Select Bill_Info1.*,mm2.WORKDAY_MM_TIME As Last_Createdate From Bill_Info Bill_Info1 Left Join T_Sys_Workday_Mm Mm2 On Mm2.Sn=(Bill_Info1.Sn+240)
), bill_info3 as ( Select Bill_Info21.*, 1 as allbill, (Case When Bill_Info21.Last_Createdate>Bill_Info21.Auditdate Then 1 Else 0 End ) As Flg From Bill_Info2 Bill_Info21 )
