Bill_Info As ( Select Bill.Orderno, To_Char(Bill.Createdate, 'YYYYMM') As Statmonth, Bill.Createdate, nvl(Bill.Auditdate,Sysdate) as Auditdate, SN as sn From Arrivals_Bill Bill left join T_SYS_WORKDAY_MM_all mm on (to_char(Bill.Createdate,'yyyy-MM-dd HH24:mi')||':00')=mm.WORKDAY_MM Where bill.ARRIVALTYPE='10' and Bill.Createdate>=TO_DATE(Extract(Year From Sysdate)-2||'0101','YYYYMMDD') Order By Bill.Createdate Asc
), Bill_Info2 As ( Select Bill_Info1.*,mm2.WORKDAY_MM_TIME As Last_Createdate From Bill_Info Bill_Info1 Left Join T_Sys_Workday_Mm Mm2 On Mm2.Sn=(Bill_Info1.Sn+240)
