From stat_week Stat_Month1 left join Bill_Info3 Bill_Info31 on Bill_Info31.stat_week=Stat_Month1.stat_week Where Substr(Stat_Month1.stat_week,0,4)>=Extract(Year From Sysdate)-2 group by substr(Stat_Month1.stat_week,0,4),Stat_Month1.stat_week )
