With Stat_Month As ( select to_char(sysdate, 'yyyy') - level + 1 stat_year from dual connect by level <= 3 order by 1 ), Stat_Qty as( Select Inco.Materialid, To_Char(Inco.Collecttime, 'yyyy') as stat_year, Sum(Inco.Qty) As Qty, 'i' as iotype From Incollectdata Inco Where Inco.Collecttime>= TO_DATE((Extract(Year From Sysdate)-2)||'-01-01','YYYY-MM-DD') GROUP BY Inco.Materialid, To_Char(Inco.Collecttime, 'yyyy') union all Select outco.Materialid,To_Char(Outco.Collecttime, 'yyyy'),Sum(outco.Qty) As Qty,'o' As Iotype From Outcollectdata Outco Where Outco.Collecttime>= To_Date((Extract(Year From Sysdate)-2)||'-01-01','YYYY-MM-DD') GROUP BY outco.Materialid, To_Char(Outco.Collecttime, 'yyyy')
), Stat_Mat2 As( select stat_qty1.stat_year,count(*) as countMat From Stat_Qty Stat_Qty1 Group By Stat_Qty1.Stat_Year ), Stat_Qty2 As( select stat_qty1.stat_year,sum(stat_qty1.Qty) as qty From Stat_Qty Stat_Qty1 Group By Stat_Qty1.Stat_Year )
Select Stat_Month1.stat_year as data1, Round(Nvl(Stat_Mat21.countMat,0),0) As Data2, Round(Nvl(stat_qty21.Qty,0)/10000,2) As Data3 From Stat_Month Stat_Month1 Left Join Stat_Mat2 Stat_Mat21 On Stat_Mat21.stat_year=Stat_Month1.stat_year Left Join stat_qty2 stat_qty21 On stat_qty21.stat_year=Stat_Month1.stat_year order by Stat_Month1.stat_year asc

