Select Bill.Orderno As Data1, Bill.Po_Number As Data2, Bill.Prodate As Data3, Bill.Data10 As data4, Pm.Matcode As Data5, pm.MATNAME as data6,
Detail.Subinventory_Code As Data7, Detail.TASKQTY as qty, Detail.Batchno As Batchno, detail.sn as sn From Inproof Bill Left Join inbill Detail On bill.inproofid=Detail.inproofid Left Join Pm_Material Pm On Detail.Materialid=Pm.Pm_Materialid left join PARTNER pa on Bill.PARTNERID=pa.PARTNERID
Where bill.PROTYPE='10' and bill.Orderno= #{data1}
